// Perception calculator: the TS port of python/awr/sim/perception/{optics,johnson,level,feasibility,refs}.py (M19-FR-022;
// AWR-04 §6.1, §6.2, §9.2, §10.3; M18-M19 PRD §6.6, §6.7, §6.13; ADR-100, ADR-101). Owner: M19.
// Used by the shared-view calculator (GSD, pixels, TTPF and the feasible window for a class, viewer, no write requests,
// D2-AC-37), the fleet clone form and the payload controls (instant GSD and identification ranges, M15-FR-211). Results equal
// the Python reference within 1 % on apps/web/tests/m19/calc_cases.json (generated by tests/perception/test_calc_golden.py).
//   N = d_c f / (R p'), GSD = R p' / f, p' = max(p_eff, lambda F#); TTPF P = x^E / (1 + x^E), x = N / N50, E = 2.7 + 0.7 x
//   N_eff = N k_los k_c k_light k_blur (1 - occlusion)
//   uniform extinction: sigma_550 = ln20 / MOR, Kim ratio (lambda / 550)^-q(V2) with V2 = ln50 / sigma_550 (km), LWIR water vapour
// The keepout lower bound of the window uses the configured sensitivity volumes (geometric; for the physical mode they
// are an upper bound of the effective volumes, which only the server evaluates: POST .../perception/feasibility).
import { CLASS_DEFAULTS, criticalDim, keepoutVolumes, type SensitivityBody, type TargetClassName, type Volume } from '@/engine/targets'
import { K_MOR, LEVEL_NAMES, N50_PX, N_P90, PERCEPTION_LEVELS, type LevelName, type Limiting, type ReqLevel } from './levels'

const L = PERCEPTION_LEVELS
const K_V2 = Math.log(50)
export const LAMBDA_NM = { eo: 550, nir: 850, lwir: 10000 } as const
export type SensorKindP = keyof typeof LAMBDA_NM
export type Light = 'day' | 'low' | 'night'
/** worst illuminance of each band (AWR-04 §6.5): 1.2e5 sin 6 deg, 3 lx, 0.001 lx */
export const BAND_LUX: Readonly<Record<Light, number>> = { day: 1.2e5 * Math.sin((6 * Math.PI) / 180), low: 3.0, night: 0.001 }

export interface IlluminatorP {
  kind: string
  pW: number
  /** null: follows the current HFOV (GX40 built-in) */
  divergenceDeg: number | null
  rRefM: number
  pRefW: number
  thetaRefDeg: number
  rhoRef: number
}

export interface SensorP {
  name: string
  kind: SensorKindP
  pixelUm: number
  wNativePx: number
  hNativePx: number
  fMinMm: number
  fMaxMm: number
  fNumberMin: number
  fNumberMax: number
  /** output name -> [w_out_px, crop_w_px] */
  outputs: Readonly<Record<string, readonly [number, number]>>
  cropHPx?: Readonly<Record<string, number>>
  analysis: string
  fLaw: 'linear_f' | 'linear_ln_f'
  netdK: number
  sigmaClutterK: readonly [number, number]
  eMinColorLx: number
  eMinMonoLx: number
  illuminators: readonly IlluminatorP[]
  pitchMinDeg: number
  pitchMaxDeg: number
  jitterShortUrad: number
  jitterLongUrad: number
  tExpDayS: number
  tExpLowS: number
  tIntS: number
  switchLx: number
  jitterFastMaxS: number
}

export interface EnvP {
  illumLx: number
  band: Light
  morM: number
  rhoVGm3: number
  kCross: number
  tBgC: number
  epsBg: number
  tSkyC: number
}

export interface ThermalP { mode: 'relative' | 'absolute'; deltaTK: number; tSurfaceC: number; emissivity: number; hotFraction: number }

export interface TargetP {
  size: readonly [number, number, number]
  contrast0: number
  camouflage: number
  reflect850: number
  thermal: ThermalP
  occlusion: number
  criticalDimM: number | null
  levelReq: ReqLevel
  nReqPx: number | null
  moving: boolean
  speedMaxMps: number
  bodies: readonly SensitivityBody[]
}

export interface PairGeom {
  rangeM: number
  /** look-down angle seen from the target (sensor above: positive), rad */
  epsRad: number
  /** sensor azimuth relative to the target heading, rad */
  betaRad: number
  /** worst aspect (planning); default: the target is moving */
  worst?: boolean
  kLos?: number
  tracking?: boolean
  vRelPerpMps?: number
  inFov?: boolean
  inIllumCone?: boolean
}

export interface LevelOut {
  level: number
  levelName: LevelName
  n: number
  nEff: number
  nReq: number
  p: number
  gsdM: number
  rangeM: number
  k: { los: number; c: number; light: number; blur: number; occ: number }
  limiting: Limiting | null
  dtAppK: number | null
}

export const defaultEnv = (light: Light = 'day', morM = 20000): EnvP =>
  ({ illumLx: BAND_LUX[light], band: light, morM, rhoVGm3: 7.5, kCross: 1, tBgC: 20, epsBg: 0.95, tSkyC: -20 })

// ------------------------------------------------------------------------------------------------ optics
const clamp01 = (x: number): number => Math.min(1, Math.max(0, x))

export function fNumber(sn: SensorP, fMm: number): number {
  if (sn.fMaxMm <= sn.fMinMm) return sn.fNumberMin
  const u = sn.fLaw === 'linear_ln_f'
    ? (Math.log(Math.max(fMm, 1e-9)) - Math.log(sn.fMinMm)) / (Math.log(sn.fMaxMm) - Math.log(sn.fMinMm))
    : (fMm - sn.fMinMm) / (sn.fMaxMm - sn.fMinMm)
  return sn.fNumberMin + (sn.fNumberMax - sn.fNumberMin) * clamp01(u)
}

export function pEffUm(sn: SensorP, resolution?: string | null): number {
  const o = sn.outputs[resolution ?? sn.analysis]
  return o ? (sn.pixelUm * o[1]) / o[0] : sn.pixelUm
}

/** effective pixel p' = max(p_eff, lambda F#) (diffraction; lambda by sensor kind) */
export function pPrimeUm(sn: SensorP, fMm: number, resolution?: string | null): number {
  return Math.max(pEffUm(sn, resolution), (LAMBDA_NM[sn.kind] / 1000) * fNumber(sn, fMm))
}

export function hfovRad(sn: SensorP, fMm: number, resolution?: string | null): number {
  const o = sn.outputs[resolution ?? sn.analysis]
  const crop = o ? o[1] : sn.wNativePx
  return 2 * Math.atan((crop * sn.pixelUm * 1e-3) / (2 * fMm))
}

export function vfovRad(sn: SensorP, fMm: number, resolution?: string | null): number {
  const h = sn.cropHPx?.[resolution ?? sn.analysis] ?? sn.hNativePx
  return 2 * Math.atan((h * sn.pixelUm * 1e-3) / (2 * fMm))
}

/** ground sample distance (m) at slant range R: R p' / f */
export function gsdM(rM: number, pUm: number, fMm: number): number {
  return (rM * pUm * 1e-3) / fMm
}

/** pixels on the critical dimension: d_c f / (R p') */
export function pixelsOnTarget(dcM: number, fMm: number, rM: number, pUm: number): number {
  return (dcM * fMm) / (Math.max(rM, 1e-9) * pUm * 1e-3)
}

/** target transfer probability function P(N) */
export function ttpf(n: number, n50Px: number): number {
  const x = Math.max(n, 0) / n50Px
  const xe = x ** (L.ttpf.e0 + L.ttpf.e1 * x)
  return Number.isFinite(xe) ? xe / (1 + xe) : 1
}

export function nReqFor(levelReq: ReqLevel = 'R', nReqPx: number | null = null): number {
  return nReqPx ?? N_P90[levelReq]
}

export function levelOf(nEff: number): number {
  return nEff >= N_P90.I ? 3 : nEff >= N_P90.R ? 2 : nEff >= N_P90.D ? 1 : 0
}

export function levelReqOf(nReq: number): ReqLevel {
  for (const k of ['D', 'R', 'I'] as const) if (Math.abs(N_P90[k] - nReq) < 1e-9) return k
  let best: ReqLevel = 'R'
  let found = false
  for (const k of ['D', 'R', 'I'] as const) {
    if (nReq >= N_P90[k]) {
      best = k
      found = true
    }
  }
  return found ? best : 'R'
}

function kimQ(v2Km: number): number {
  if (v2Km > 50) return 1.6
  if (v2Km > 6) return 1.3
  if (v2Km > 1) return 0.16 * v2Km + 0.34
  if (v2Km > 0.5) return v2Km - 0.5
  return 0
}

/** uniform extinction coefficient (1/m) at a wavelength (same formula as M07 sigma_lambda for a ground point) */
export function sigmaPerM(morM: number, lamNm: number, rhoVGm3 = 7.5): number {
  let s = 0
  if (morM > 0 && Number.isFinite(morM)) {
    const s550 = K_MOR / morM
    s = lamNm === 550 ? s550 : s550 * (lamNm / 550) ** -kimQ(K_V2 / s550 / 1000)
  }
  if (lamNm >= 8000) s += (0.03 + 0.012 * Math.max(0, rhoVGm3)) / 1000
  return s
}

/** illuminator effective range R_nir = R0 tau_850(R_nir) (fixed point of AWR-20 §6.3, solved by bisection: g(x) = x - R0 exp(-sigma x)
 *  increases monotonically; plain iteration oscillates in dense fog when sigma R_nir > 1) */
export function rNirFixedPoint(r0: number, sigmaPerM_: number): number {
  let lo = 0
  let hi = r0
  for (let i = 0; i < 50; i++) {
    const mid = 0.5 * (lo + hi)
    if (mid - r0 * Math.exp(-sigmaPerM_ * mid) >= 0) hi = mid
    else lo = mid
  }
  return 0.5 * (lo + hi)
}

const kPassive = (eLx: number, eMin: number): number => clamp01(Math.log10(Math.max(eLx, 1e-12) / eMin) / L.light.decades)

// ------------------------------------------------------------------------------------------------ unified criterion
export interface LevelInput {
  sensor: SensorP
  fMm?: number
  mode?: 'auto' | 'day' | 'lowlight' | 'nir'
  resolution?: string | null
  illumOn?: readonly boolean[]
  target: TargetP
  geom: PairGeom
  env: EnvP
  nReq?: number
  /** path transmittance at the sensor wavelength (default: uniform from env.morM) */
  tauPath?: number
}

/** one (imaging sensor, target) pair, M18-M19 PRD §6.7 (same as perception_level in Python) */
export function perceptionLevel(inp: LevelInput): LevelOut {
  const sn = inp.sensor
  const T = inp.target
  const g = inp.geom
  const env = inp.env
  const f = inp.fMm ?? sn.fMaxMm
  const mode = inp.mode ?? (sn.kind === 'nir' ? 'nir' : 'auto')
  const nReq = inp.nReq ?? nReqFor(T.levelReq, T.nReqPx)
  const R = Math.max(g.rangeM, 1e-6)
  const kLos = g.kLos ?? 1
  const inFov = g.inFov ?? true
  const pp = pPrimeUm(sn, f, inp.resolution)
  const lwir = sn.kind === 'lwir'
  const worst = g.worst ?? T.moving
  let dc = T.criticalDimM ?? criticalDim(T.size[0], T.size[1], T.size[2], g.epsRad, g.betaRad, worst)
  if (lwir) dc *= Math.sqrt(Math.max(T.thermal.hotFraction, 0.25))
  const N = (dc * f) / (R * pp * 1e-3)
  const G = (R * pp * 1e-3) / f
  const tau = inp.tauPath ?? Math.exp(-sigmaPerM(env.morM, LAMBDA_NM[sn.kind], env.rhoVGm3) * R)
  let kC: number
  let kLight: number
  let tExp: number
  let jit: number
  let dtApp: number | null = null
  const E = env.illumLx
  if (lwir) {
    const K0 = 273.15
    const ts = env.tSkyC + K0
    const tb = env.tBgC + K0
    const th = T.thermal
    dtApp = th.mode === 'absolute'
      ? tau * (th.emissivity * (th.tSurfaceC + K0) + (1 - th.emissivity) * ts - env.epsBg * tb - (1 - env.epsBg) * ts)
      : tau * th.emissivity * th.deltaTK * env.kCross
    const clutter = env.band === 'day' ? sn.sigmaClutterK[0] : sn.sigmaClutterK[1]
    const snr = Math.abs(dtApp) / Math.sqrt(sn.netdK ** 2 + clutter ** 2)
    kC = clamp01((snr - L.lwir.snr_min) / L.lwir.snr_span)
    kLight = 1
    tExp = sn.tIntS
    jit = sn.jitterShortUrad
  } else {
    const C = Math.abs(T.contrast0) * (1 - T.camouflage) * tau
    kC = clamp01((C - L.contrast.c_min) / (L.contrast.c_full - L.contrast.c_min))
    const kc = kPassive(E, sn.eMinColorLx)
    const km = kPassive(E, sn.eMinMonoLx)
    if (sn.kind === 'nir') {
      const t850 = inp.tauPath ?? Math.exp(-sigmaPerM(env.morM, 850, env.rhoVGm3) * R)
      const sig850 = R > 0 ? -Math.log(Math.max(t850, 1e-300)) / R : 0
      let active = 0
      const hf = hfovRad(sn, f, inp.resolution)
      sn.illuminators.forEach((il, j) => {
        const on = inp.illumOn
        if (on && on.length > 0 && !(j < on.length && on[j])) return
        if (g.inIllumCone === false) return
        const thDeg = il.divergenceDeg ?? (hf * 180) / Math.PI
        const r0 = il.rRefM * (il.thetaRefDeg / Math.max(thDeg, 1e-9)) * Math.sqrt(il.pW / il.pRefW) * Math.sqrt(Math.max(T.reflect850, 0) / il.rhoRef)
        const rn = rNirFixedPoint(r0, sig850)
        const k = rn > 0 ? clamp01((rn - R) / (L.light.nir_edge_frac * rn)) : 0
        active = Math.max(active, k)
      })
      kLight = Math.max(active, km)
      tExp = sn.tExpLowS
    } else {
      kLight = mode === 'day' ? kc : mode === 'lowlight' || mode === 'nir' ? km : Math.max(kc, km)
      tExp = E >= sn.switchLx ? sn.tExpDayS : sn.tExpLowS
    }
    jit = tExp <= sn.jitterFastMaxS ? sn.jitterShortUrad : sn.jitterLongUrad
  }
  const v = Math.abs(g.vRelPerpMps ?? 0)
  const vRes = (g.tracking ?? true) ? L.blur.track_residual * v : v
  const b = vRes * tExp + R * jit * 1e-6
  const kBlur = G > 0 ? G / Math.sqrt(G * G + b * b) : 0
  const occ = T.occlusion
  const nMax = N * kC * kLight * kBlur * (1 - occ)
  const nEff = inFov ? nMax * kLos : 0
  let limiting: Limiting | null
  if (!inFov) limiting = 'fov'
  else if (nEff >= nReq) limiting = null
  else if (N < nReq) limiting = 'pixels'
  else {
    const c: [number, Limiting][] = [[kLos * (1 - occ), 'los'], [kLight, 'light'], [kC, 'contrast'], [kBlur, 'blur']]
    let m = c[0]
    for (const x of c) if (x[0] < m[0]) m = x
    limiting = m[1]
  }
  const level = levelOf(nEff)
  return {
    level, levelName: LEVEL_NAMES[level], n: N, nEff, nReq, p: ttpf(nEff, N50_PX[levelReqOf(nReq)]), gsdM: G, rangeM: R,
    k: { los: kLos, c: kC, light: kLight, blur: kBlur, occ }, limiting, dtAppK: dtApp,
  }
}

/** focal length (mm) that puts nTarget pixels on d_c at slant range R, clamped to the lens (p' depends on f: 3 passes) */
export function zoomForLevel(sn: SensorP, rM: number, dcM: number, nTarget: number): number {
  let f = sn.fMaxMm
  for (let i = 0; i < 3; i++) f = Math.min(Math.max((nTarget * rM * pPrimeUm(sn, f) * 1e-3) / Math.max(dcM, 1e-9), sn.fMinMm), sn.fMaxMm)
  return f
}

// ------------------------------------------------------------------------------------------------ feasibility window
export interface FeasibilityInput {
  target: TargetP
  sensor: SensorP
  light: Light
  morM: number
  levelReq?: ReqLevel
  /** horizontal hold sigma of the vehicle (RTK 0.02 m): margin = 20 m + 3 sigma */
  holdSigmaM?: number
  aglM?: readonly number[]
  env?: EnvP
}

export interface FeasibilityOut {
  dLoM: number | null
  dHiM: number | null
  aglM: number | null
  why: string | null
}

/** horizontal radius of the keepouts at aglM above the target base (spheres and hemispheres cut at that height) */
export function keepoutHorizontalRadius(vols: readonly Volume[], aglM: number, baseZ = 0): number {
  const z = baseZ + aglM
  let r = 0
  for (const v of vols) {
    if (v.shape === 'sphere' || v.shape === 'hemisphere') {
      const dz = z - v.center[2]
      if (v.shape === 'hemisphere' && dz < 0) continue
      r = Math.max(r, Math.sqrt(Math.max(v.rM * v.rM - dz * dz, 0)))
    } else if (v.zMinM <= z && z <= v.zMaxM) {
      r = Math.max(r, v.rM)
    }
  }
  return r
}

const WHY_ORDER = ['narrow', 'keepout_gt_range', 'light', 'contrast', 'blur', 'los', 'pixels']

/** feasible window with the AGL used and the reason when infeasible (Python feasibility_detail) */
export function feasibilityDetail(inp: FeasibilityInput): FeasibilityOut {
  const T = inp.target
  const sn = inp.sensor
  const F = L.feasibility
  const margin = F.margin_base_m + F.margin_sigma_k * (inp.holdSigmaM ?? 0.02)
  const vols = keepoutVolumes(T.bodies, [0, 0, 0], 0, T.moving, margin)
  const env = inp.env ?? defaultEnv(inp.light, inp.morM)
  const nReq = nReqFor(inp.levelReq ?? 'R', T.nReqPx)
  const [l, w, h] = T.size
  const pp = pPrimeUm(sn, sn.fMaxMm)
  const dcMax = T.criticalDimM ?? Math.sqrt(l * w + Math.min(w * h, l * h))
  const dMax = Math.min(20000, (dcMax * sn.fMaxMm) / (nReq * pp * 1e-3))
  const n = Math.floor(dMax) + 2
  const speed = T.moving ? T.speedMaxMps : 0
  let best: [number, number, number] | null = null
  const votes: string[] = []
  for (const agl of inp.aglM ?? F.agl_m) {
    const dLo = keepoutHorizontalRadius(vols, agl)
    const ok = (d: number): { ok: boolean; lim: Limiting | null } => {
      const R = Math.hypot(d, agl)
      const r = perceptionLevel({ sensor: sn, target: T, env, nReq, geom: { rangeM: R, epsRad: Math.atan2(agl, d), betaRad: 0, worst: true, tracking: true, vRelPerpMps: speed } })
      return { ok: r.nEff >= nReq, lim: r.limiting }
    }
    const s = Math.ceil(dLo - 1e-9)
    const first = s < n ? ok(s) : null
    if (first === null || !first.ok) {
      let anyBefore = false
      for (let d = 0; d < Math.min(s, n); d++) if (ok(d).ok) { anyBefore = true; break }
      votes.push(anyBefore ? 'keepout_gt_range' : first?.lim ?? 'pixels')
      continue
    }
    let d = s
    while (d + 1 < n && ok(d + 1).ok) d++
    if (d - dLo < F.w_min_m) {
      votes.push('narrow')
      continue
    }
    if (best === null || d - dLo > best[1] - best[0]) best = [Math.round(dLo * 10) / 10, d, agl]
  }
  if (best) return { dLoM: best[0], dHiM: best[1], aglM: best[2], why: null }
  return { dLoM: null, dHiM: null, aglM: null, why: WHY_ORDER.find((x) => votes.includes(x)) ?? 'pixels' }
}

/** horizontal station window [dLoM, dHiM] (m) or null (AWR-04 §9.2; Python feasibility_window) */
export function feasibilityWindow(inp: FeasibilityInput): { dLoM: number; dHiM: number } | null {
  const r = feasibilityDetail(inp)
  return r.why === null && r.dLoM !== null && r.dHiM !== null ? { dLoM: r.dLoM, dHiM: r.dHiM } : null
}

/** largest slant range (m) with N_eff >= the level's pixels, horizontal view (eps = 0), static target, clear line of sight */
export function maxRangeForLevel(sn: SensorP, T: TargetP, env: EnvP, level: ReqLevel, opts: { fMm?: number; resolution?: string | null } = {}): number {
  const nReq = N_P90[level]
  const at = (R: number) => perceptionLevel({ sensor: sn, fMm: opts.fMm, resolution: opts.resolution, target: T, env, nReq,
    geom: { rangeM: R, epsRad: 0, betaRad: 0, worst: true, vRelPerpMps: 0 } }).nEff
  let lo = 0.1
  let hi = 20000
  if (at(lo) < nReq) return 0
  for (let i = 0; i < 60; i++) {
    const mid = 0.5 * (lo + hi)
    if (at(mid) >= nReq) lo = mid
    else hi = mid
  }
  return lo
}

// ------------------------------------------------------------------------------------------------ inputs
/** target parameters from a class template (engine/targets CLASS_DEFAULTS) with overrides */
export function targetFromClass(cls: TargetClassName, over: Partial<TargetP> = {}): TargetP {
  const c = CLASS_DEFAULTS[cls] as unknown as Record<string, unknown>
  const s = c.size_m as { l: number; w: number; h: number }
  const th = (c.thermal ?? {}) as Record<string, number | string>
  const mo = (c.motion ?? {}) as Record<string, number | string>
  const moving = (mo.mode ?? 'static') !== 'static'
  return {
    size: [s.l, s.w, s.h], contrast0: Number(c.contrast0 ?? 0.3), camouflage: Number(c.camouflage ?? 0), reflect850: Number(c.reflect_850 ?? 0.3),
    thermal: { mode: (th.mode as 'relative' | 'absolute') ?? 'relative', deltaTK: Number(th.delta_t_k ?? 0), tSurfaceC: Number(th.t_surface_c ?? 30),
      emissivity: Number(th.emissivity ?? 0.95), hotFraction: Number(th.hot_fraction ?? 1) },
    occlusion: Number(c.occlusion ?? 0), criticalDimM: (c.critical_dim_m as number | null) ?? null, levelReq: ((c.level_req as ReqLevel) ?? 'R'),
    nReqPx: (c.n_req_px as number | null) ?? null, moving, speedMaxMps: moving ? Number(mo.speed_max_mps ?? 0) : 0,
    bodies: ((c.sensitivity ?? []) as SensitivityBody[]), ...over,
  }
}

const BL = L.blur
const base = (name: string, kind: SensorKindP): Omit<SensorP, 'pixelUm' | 'wNativePx' | 'hNativePx' | 'fMinMm' | 'fMaxMm' | 'fNumberMin' | 'fNumberMax'> => ({
  name, kind, outputs: {}, analysis: 'native', fLaw: 'linear_f', netdK: 0.05, sigmaClutterK: [L.lwir.sigma_clutter_k.day, L.lwir.sigma_clutter_k.night],
  eMinColorLx: L.light.e_min_color_lx, eMinMonoLx: L.light.e_min_mono_lx, illuminators: [], pitchMinDeg: -90, pitchMaxDeg: 30,
  jitterShortUrad: BL.jitter_short_urad, jitterLongUrad: BL.jitter_long_urad, tExpDayS: BL.t_exp_day_s, tExpLowS: BL.t_exp_low_s, tIntS: BL.t_exp_lwir_s,
  switchLx: BL.switch_lx, jitterFastMaxS: BL.t_short_max_s,
})

/** GX40 built-in 850 nm illuminator and the external nir_ill_l (vehicles/sensor_models) */
export const GX40_BUILTIN: IlluminatorP = { kind: 'builtin', pW: 0.8, divergenceDeg: null, rRefM: 200, pRefW: 0.8, thetaRefDeg: 6.6, rhoRef: 0.3 }
export const NIR_ILL_L: IlluminatorP = { kind: 'nir_ill_l', pW: 3.0, divergenceDeg: 5.5, rRefM: 200, pRefW: 0.8, thetaRefDeg: 6.6, rhoRef: 0.3 }

/** reference GX40 (vehicles/sensor_models/eo_gx40.yaml): 3840 x 2160, 1.45 um, 4.8-48 mm, F1.7-3.2 */
export function gx40(analysis = '1080p', opts: { night?: boolean; ext?: boolean } = {}): SensorP {
  return {
    ...base('eo_gx40', opts.night ? 'nir' : 'eo'), pixelUm: 1.45, wNativePx: 3840, hNativePx: 2160, fMinMm: 4.8, fMaxMm: 48, fNumberMin: 1.7, fNumberMax: 3.2,
    outputs: { '4k': [3840, 3840], '1080p': [1920, 3840], '720p': [1280, 3840], sxga: [1280, 2700], '1p3m': [1280, 2880] },
    cropHPx: { '4k': 2160, '1080p': 2160, '720p': 2160, sxga: 2160, '1p3m': 2160 }, analysis,
    illuminators: opts.ext ? [GX40_BUILTIN, NIR_ILL_L] : [GX40_BUILTIN],
  }
}

/** reference LWIR 640 x 512, 12 um, NETD 50 mK, lens 13 / 25 / 75 / 100 mm F1.0 */
export function lwir640(lensMm = 100): SensorP {
  return {
    ...base('lwir640', 'lwir'), pixelUm: 12, wNativePx: 640, hNativePx: 512, fMinMm: lensMm, fMaxMm: lensMm, fNumberMin: 1, fNumberMax: 1,
    jitterShortUrad: BL.jitter_lwir_urad, jitterLongUrad: BL.jitter_lwir_urad,
  }
}

const num = (v: unknown, d: number): number => (typeof v === 'number' && Number.isFinite(v) ? v : d)

/** a catalog sensor item (GET /api/sandbox/v1/catalog/sensors, stores/catalog SensorItem) as calculator input; null for
 *  non-imaging sensors. `night` makes an EO sensor with illuminators a NIR sensor; `ext` adds the external illuminator. */
export function sensorFromCatalog(item: { sensor_type: string; kind: string; spec: Record<string, unknown> },
  opts: { lensMm?: number; resolution?: string; night?: boolean; ext?: IlluminatorP | null } = {}): SensorP | null {
  const s = item.spec ?? {}
  if (item.kind === 'eo' || item.kind === 'nir') {
    const f = (s.f_mm as number[] | undefined) ?? [4.8, 48]
    const fn = (s.f_number as number[] | undefined) ?? [1.7, 3.2]
    const outs: Record<string, readonly [number, number]> = {}
    const ch: Record<string, number> = {}
    for (const o of (s.outputs as Record<string, unknown>[] | undefined) ?? []) {
      outs[String(o.name)] = [num(o.w_px, 1920), num(o.crop_w_px, num(s.native_w_px, 3840))]
      ch[String(o.name)] = num(o.crop_h_px, num(s.native_h_px, 2160))
    }
    const ill: IlluminatorP[] = []
    const il = s.illuminator as Record<string, unknown> | undefined
    if (il) ill.push({ kind: 'builtin', pW: num(il.power_w, 0.8), divergenceDeg: null, rRefM: num(il.range_ref_m, 200), pRefW: num(il.power_w, 0.8),
      thetaRefDeg: num(il.divergence_ref_deg, 6.6), rhoRef: 0.3 })
    if (opts.ext) ill.push(opts.ext)
    const g = s.gimbal as { pitch_deg?: number[] } | undefined
    return {
      ...base(item.sensor_type, opts.night && ill.length > 0 ? 'nir' : 'eo'), pixelUm: num(s.pixel_um, 1.45), wNativePx: num(s.native_w_px, 3840),
      hNativePx: num(s.native_h_px, 2160), fMinMm: f[0], fMaxMm: f[1], fNumberMin: fn[0], fNumberMax: fn[1], outputs: outs, cropHPx: ch,
      analysis: opts.resolution ?? (typeof s.analysis_default === 'string' ? s.analysis_default : '1080p'), eMinColorLx: num(s.min_lux_color, L.light.e_min_color_lx),
      eMinMonoLx: num(s.min_lux_mono, L.light.e_min_mono_lx), illuminators: ill, pitchMinDeg: num(g?.pitch_deg?.[0], -90),
      pitchMaxDeg: num(g?.pitch_deg?.[1], 30),
    }
  }
  if (item.kind === 'lwir') {
    const lenses = (s.lenses as Record<string, unknown>[] | undefined) ?? []
    const lens = lenses.find((x) => num(x.f_mm, 0) === opts.lensMm) ?? lenses[lenses.length - 1]
    const f = num(lens?.f_mm, opts.lensMm ?? 25)
    const fnb = num(lens?.f_number, 1)
    return {
      ...base(item.sensor_type, 'lwir'), pixelUm: num(s.pixel_um, 12), wNativePx: num(s.w_px, 640), hNativePx: num(s.h_px, 512), fMinMm: f, fMaxMm: f,
      fNumberMin: fnb, fNumberMax: fnb, netdK: num(s.netd_mk, 50) / 1000, jitterShortUrad: BL.jitter_lwir_urad, jitterLongUrad: BL.jitter_lwir_urad,
    }
  }
  return null
}

/** the external illuminator of a catalog item of kind nir_illuminator */
export function illuminatorFromCatalog(item: { sensor_type: string; spec: Record<string, unknown> }): IlluminatorP {
  const s = item.spec ?? {}
  const ref = (s.ref ?? {}) as Record<string, unknown>
  return { kind: item.sensor_type, pW: num(s.power_w, 3), divergenceDeg: num(s.divergence_deg, 5.5), rRefM: num(ref.r_m, 200), pRefW: num(ref.p_w, 0.8),
    thetaRefDeg: num(ref.theta_deg, 6.6), rhoRef: num(ref.rho, 0.3) }
}

// ------------------------------------------------------------------------------------------------ UI summaries
export interface SensorSummary {
  fMm: number
  hfovDeg: number
  pPrimeUm: number
  /** GSD (m) at 100 m slant range */
  gsdAt100M: number
  /** largest slant range (m) per level for the class (horizontal, clear, static; EO day, NIR and LWIR night) */
  maxRangeM: Record<ReqLevel, number>
  /** station window for the class (geometric keepouts), day and night; null when infeasible */
  window: Partial<Record<Light, { dLoM: number; dHiM: number } | null>>
}

/** instant hints of the clone form and the payload controls (M15-FR-211 item 2; 14 §20.9) */
export function sensorSummary(sn: SensorP, opts: { fMm?: number; resolution?: string | null; cls?: TargetClassName; morM?: number; holdSigmaM?: number } = {}): SensorSummary {
  const f = opts.fMm ?? sn.fMaxMm
  const pp = pPrimeUm(sn, f, opts.resolution)
  const T = targetFromClass(opts.cls ?? 'person')
  const light: Light = sn.kind === 'eo' ? 'day' : 'night'
  const env = { ...defaultEnv(light, opts.morM ?? 10000), illumLx: light === 'day' ? 1e5 : 0.001, rhoVGm3: 10 }
  const st = { ...T, moving: false, speedMaxMps: 0 }
  const window: SensorSummary['window'] = {}
  for (const lt of (sn.kind === 'eo' ? ['day'] : ['night']) as Light[]) {
    window[lt] = feasibilityWindow({ target: T, sensor: sn, light: lt, morM: opts.morM ?? 10000, holdSigmaM: opts.holdSigmaM })
  }
  return {
    fMm: f, hfovDeg: (hfovRad(sn, f, opts.resolution) * 180) / Math.PI, pPrimeUm: pp, gsdAt100M: gsdM(100, pp, f),
    maxRangeM: { D: maxRangeForLevel(sn, st, env, 'D', opts), R: maxRangeForLevel(sn, st, env, 'R', opts), I: maxRangeForLevel(sn, st, env, 'I', opts) },
    window,
  }
}

/** GSD (m) of a sensor at focal length fMm and slant range rM (payload zoom slider hint) */
export function gsdAtRange(sn: SensorP, fMm: number, rM: number, resolution?: string | null): number {
  return gsdM(rM, pPrimeUm(sn, fMm, resolution), fMm)
}

